\documentclass{article}
\usepackage{pgfplots}
\usepackage{hyperref}
\usepackage{graphicx}
\usepackage{amsmath}
\usepackage{cancel}
%% For tabular environment
\usepackage[T1]{fontenc}
\usepackage{makecell}
\usetikzlibrary{shapes,calc,positioning} 
\usepackage{tkz-euclide}
\usetkzobj{all}
\usepackage{tikz-3dplot}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{document}

\pagestyle{empty}

\tdplotsetmaincoords{70}{0}
\begin{tikzpicture}[tdplot_main_coords, scale=0.75]
 \def\acolor{darkgreen};
 \def\radius{3};
 \def\height{4.5};
    \coordinate (O) at (0,0,\height);
    \coordinate (O2) at (0,0,0);
    \coordinate (B) at (\radius,0,0);
    \coordinate (E) at (\radius,0,\height);
    \coordinate (A) at (-\radius,0,0);
    \coordinate (F) at (-\radius,0,\height);


    \begin{scope}[canvas is xy plane at z=0]
            \draw[color=\acolor!20,fill=\acolor!20,fill opacity=0.6,opacity=0.6] (O2) circle (\radius);
            \draw[color=\acolor!20,fill=\acolor!10,fill opacity=0.6,opacity=0.6] (O) circle (\radius);
            \draw[very thick, \acolor,dashed] (B) arc (0:180:\radius);
            \draw[very thick, \acolor,left color=\acolor!40, right color=\acolor!70, middle color=\acolor!30,fill opacity=0.6] (B) arc  (0:-180:\radius)-- (F) arc  (-180:0:\radius) --cycle;

            \draw[very thick, \acolor] (F) arc (180:0:\radius);


	\end{scope}

    %\draw(E) -- (B) (A)--(F);
    \tkzLabelSegment[right](E,B){ {\small $14\,\textrm{cm}$}}
    \tkzLabelSegment[above](E,O){ {\small $9\,\textrm{cm}$}}
    \tkzDrawPoint[color=none, fill=\acolor](O)
    \tkzDrawSegment[very thick, \acolor](E,O)

\end{tikzpicture}

\end{document}

